exercises.solution:
class Thermostat {
  #temp = 20;
  warmer() { this.#temp += 1; }
  getTemp() { return this.#temp; }
}
const t = new Thermostat();
t.warmer();
t.warmer();
console.log("temp:", t.getTemp());

