exercises.solution:
class Account {
  #balance = 100;
  withdraw(amount) {
    if (amount <= this.#balance) this.#balance -= amount;
  }
  getBalance() { return this.#balance; }
}
const a = new Account();
a.withdraw(30);
a.withdraw(999);
console.log("balance:", a.getBalance());

